SELECT
    [P1].[SegmentName] AS [c0],
    (SELECT DATEADD(DAY, 365 * (((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST([N2].[v] AS int)) / 13) - 1) + ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST([N2].[v] AS int)) / 13) / 4 + 30 * ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST([N2].[v] AS int)) % 13) + LEAST(((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) % 30, (29 - ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST([N2].[v] AS int)) % 13) / 12 * (25 - ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST([N2].[v] AS int)) / 13) % 4 / 3))) - (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922), [N1].[v]) FROM (VALUES (MAX([T].[PostingDate]))) AS [N1] ([v]) CROSS APPLY (VALUES (COUNT_BIG([T].[DocumentId]))) AS [N2] ([v])) AS [c1],
    (SELECT (SELECT DATEADD(DAY, DATEDIFF(DAY, [M].[StartDate], [M2].[StartDate]) + LEAST(0, DATEDIFF(DAY, [M2].[StartDate], [M2].[EndDate]) - 1 - DATEDIFF(DAY, [M].[StartDate], [V2].[v])), [V2].[v]) FROM [core].[CalendarMonths] AS [M2] CROSS APPLY (VALUES (COUNT_BIG([T].[DocumentId]))) AS [V1] ([v]) WHERE [M2].[Calendar] = @qx0_p0 AND [M2].[Year] = (([M].[Year] * 12 + [M].[Month] - 1 + CAST([V1].[v] AS int)) / 12) AND [M2].[Month] = (([M].[Year] * 12 + [M].[Month] - 1 + CAST([V1].[v] AS int)) % 12 + 1)) FROM (VALUES (MAX([T].[PostingDate]))) AS [V2] ([v]) CROSS APPLY (SELECT TOP (1) [M].[Year], [M].[Month], [M].[StartDate], [M].[EndDate] FROM [core].[CalendarMonths] AS [M] WHERE [M].[Calendar] = @qx0_p0 AND [M].[StartDate] <= [V2].[v] ORDER BY [M].[StartDate] DESC) AS [M] WHERE [V2].[v] < [M].[EndDate]) AS [c2],
    (SELECT (SELECT DATEADD(DAY, DATEDIFF(DAY, [M].[StartDate], [M2].[StartDate]) + LEAST(0, DATEDIFF(DAY, [M2].[StartDate], [M2].[EndDate]) - 1 - DATEDIFF(DAY, [M].[StartDate], [V1].[v])), [V1].[v]) FROM [core].[CalendarMonths] AS [M2] WHERE [M2].[Calendar] = @qx0_p0 AND [M2].[Year] = ([M].[Year] + CAST(COUNT_BIG([T].[DocumentId]) AS int)) AND [M2].[Month] = [M].[Month]) FROM (VALUES (MAX([T].[PostingDate]))) AS [V1] ([v]) CROSS APPLY (SELECT TOP (1) [M].[Year], [M].[Month], [M].[StartDate], [M].[EndDate] FROM [core].[CalendarMonths] AS [M] WHERE [M].[Calendar] = @qx0_p0 AND [M].[StartDate] <= [V1].[v] ORDER BY [M].[StartDate] DESC) AS [M] WHERE [V1].[v] < [M].[EndDate]) AS [c3],
    (SELECT DATEADD(DAY, 365 * CAST([N2].[v] AS int) + (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) + CAST([N2].[v] AS int)) / 4 - ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4 - ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 365 * (1 - (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) + CAST([N2].[v] AS int)) % 4 / 3), [N1].[v]) FROM (VALUES (MAX([T].[PostingDate]))) AS [N1] ([v]) CROSS APPLY (VALUES (SUM(CASE WHEN [T].[DocumentId] IS NOT NULL THEN @qx0_p1 END))) AS [N2] ([v])) AS [c4],
    (SELECT (SELECT DATEADD(DAY, DATEDIFF(DAY, [M].[StartDate], [M2].[StartDate]) + LEAST(0, DATEDIFF(DAY, [M2].[StartDate], [M2].[EndDate]) - 1 - DATEDIFF(DAY, [M].[StartDate], [V2].[v])), [V2].[v]) FROM [core].[CalendarMonths] AS [M2] CROSS APPLY (VALUES (COUNT_BIG(CASE WHEN [T].[DocumentId] IS NOT NULL THEN CASE WHEN (@qx0_p2 >= CONVERT(date, @qx0_p3, 23)) THEN 1 ELSE 0 END END))) AS [V1] ([v]) WHERE [M2].[Calendar] = @qx0_p0 AND [M2].[Year] = (([M].[Year] * 12 + [M].[Month] - 1 + CAST([V1].[v] AS int)) / 12) AND [M2].[Month] = (([M].[Year] * 12 + [M].[Month] - 1 + CAST([V1].[v] AS int)) % 12 + 1)) FROM (VALUES (MIN([T].[PostingDate]))) AS [V2] ([v]) CROSS APPLY (SELECT TOP (1) [M].[Year], [M].[Month], [M].[StartDate], [M].[EndDate] FROM [core].[CalendarMonths] AS [M] WHERE [M].[Calendar] = @qx0_p0 AND [M].[StartDate] <= [V2].[v] ORDER BY [M].[StartDate] DESC) AS [M] WHERE [V2].[v] < [M].[EndDate]) AS [c5]
FROM [gl].[Documents] AS [T]
INNER JOIN [gl].[Segments] AS [P1] ON [P1].[SegmentId] = [T].[SegmentId]
GROUP BY [P1].[SegmentName]
;

-- parameters
--   @qx0_p0 : QxString QxVarChar(8000) Literal = 'uq'
--   @qx0_p1 : QxNumeric QxDecimal(1, 0) Literal = 1
--   @qx0_p2 : QxDate QxDate Today
--   @qx0_p3 : QxString QxNVarChar(4000) Literal = '2000-01-01'
-- columns
--   0 : QxString NotNull key path=Centre.Name Centre.Name
--   1 : QxDate NotNull addMonths(max(PostingDate), count(), 'et')
--   2 : QxDate Nullable addMonths(max(PostingDate), count(), 'uq')
--   3 : QxDate Nullable addYears(max(PostingDate), count(), 'uq')
--   4 : QxDate NotNull addYears(max(PostingDate), sum(1), 'et')
--   5 : QxDate Nullable addMonths(min(PostingDate), count(today() >= cast('2000-01-01', 'date')), 'uq')
